import { describe, expect, it } from 'vitest';
import { assertGodotVersion, renderRasterModule, vendoredIconsOfSource } from './bake-theme-icons.mjs';

const PNG_SIGNATURE = Uint8Array.of(137, 80, 78, 71);

describe('renderRasterModule', () => {
  it('maps each icon key to a PNG data URL, in key order, under a GENERATED header', () => {
    const text = renderRasterModule({ unchecked: Uint8Array.of(1, 2, 3), checked: PNG_SIGNATURE }, '4.6.3');

    expect(text).toContain(
      '// GENERATED by scripts/godot-theme-icons/bake-theme-icons.mjs from Godot 4.6.3. Do not edit.'
    );
    expect(text).toContain(
      "  checked: 'data:image/png;base64,iVBORw==',\n  unchecked: 'data:image/png;base64,AQID',\n"
    );
  });
});

describe('assertGodotVersion', () => {
  it('accepts the 4.6.3 release build', () => {
    expect(() => assertGodotVersion('4.6.3.stable.official.7d41c59c4')).not.toThrow();
  });

  it('refuses another release and names the expected and the found version (error case)', () => {
    expect(() => assertGodotVersion('4.7.2.stable.official.abc')).toThrow(
      'expected Godot 4.6.3, got 4.7.2.stable.official.abc'
    );
  });
});

describe('vendoredIconsOfSource', () => {
  it('pairs each registered key with the base64 of its constant, including a constant used twice', () => {
    const source = `
      const A_B64 =
        'QQ==';
      const B_B64 = 'Qg==';
      export const T = { a: vendoredIcon('alpha', A_B64), b: vendoredIcon('beta', B_B64), c: vendoredIcon('alpha', A_B64) };`;

    expect(vendoredIconsOfSource(source)).toEqual([
      ['alpha', 'QQ=='],
      ['beta', 'Qg=='],
      ['alpha', 'QQ=='],
    ]);
  });

  it('refuses a call whose constant is missing and names both (error case)', () => {
    expect(() => vendoredIconsOfSource("vendoredIcon('alpha', A_B64)")).toThrow(
      'expected a const A_B64 for the icon alpha'
    );
  });
});
